  criteria: {
    older_than: string;
    inactive_for: string;
    liveness_guard: string;
  };
  sessions: Array<{
    session_id: string;
    status: string;
    reason: string;
    close_reason?: string;
  }>;
  totals: {
    active_sessions_total: number;
    sessions_evaluated: number;
    candidates: number;
    changed_sessions: number;
    skipped_sessions: number;
    failures: number;
  };
}

interface JsonErrorPayload {
  success: false;
  error: string;
  details?: {
    field?: string;
    value?: string;
    guidance?: string;
  };
}

describe("session stale close", () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
