    await createSession(tempDir, {
      id: sessionId,
      agent_type: "test-agent",
      status: "active",
      started_at: startedAt,
    });

    if (lastActivityAt) {
      await appendEvent(tempDir, {
        session_id: sessionId,
        type: "session.update",
        ts: new Date(lastActivityAt).getTime(),
        data: { update: "heartbeat" },
