  it('should stop then start on restart', async () => {
    if (!bunAvailable) {
      console.log('  ⊘ Skipping test - Bun runtime required');
      return;
    }

    const port = await getAvailablePort();

    // Start daemon
    kspec(
      `serve start --daemon --port ${port} --kspec-dir ${join(tempDir, '.kspec')}`,
