    const child = spawn('node', [
      join(__dirname, '../dist/cli/index.js'),
      'serve',
      'start',
      '--port',
      String(port),
      '--kspec-dir',
      join(tempDir, '.kspec')
    ], {
      cwd: tempDir,
      stdio: ['pipe', 'pipe', 'pipe'],
    });

    let output = '';
    child.stdout?.on('data', (data) => {
      output += data.toString();
    });

    child.stderr?.on('data', (data) => {
      output += data.toString();
    });

