/**
 * Tests for staleness detection
 * AC: @stale-status-detection
 */
describe("Staleness detection", () => {
  let tmpDir: string;

  beforeEach(async () => {
    tmpDir = await createTempDir("kspec-staleness-test-");
    initGitRepo(tmpDir);
  });

